use super::*;
use semio_framework_value::retained_clone::RetainedCloneSource;
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe<T>(op:impl FnOnce()->T)->(T,(usize,usize)){let(v,a,b)=crate::test_allocation::observe_backing(op);(v,(a,b))}
fn source(value:u32)->RetainedCloneSource<u32>{let d=RetainedCloneSource::<u32>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<u32>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).unwrap_or_else(|_|panic!("original unsigned source")).0}
#[test]
fn original_unsigned_diagnostic_targets_preserve_source_binding_and_paid_decimal_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){let mut original=source(case["value"].as_u64().unwrap()as u32);let mut foreign=source(case["value"].as_u64().unwrap()as u32);let target=[RetainedDiagnosticTarget::Unsigned(original.borrow())];for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut owner=RetainedDiagnosticPreparation::<1>::default();owner.start(RetainedDiagnosticSpec{level:Severity::Error,code:"mutation.target-missing",message:"The addressed entity is missing."},grant(RetainedDiagnosticPreparation::<1>::start_demand())).unwrap();let mut done=false;let mut turns=0;while cut.is_none_or(|cut|turns<cut){let d=owner.target_demand(target,4096).unwrap();let g=grant(d);for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:0,..g},RetainedCloneGrant{maximum_release_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{if retained_mutation_demand_fits(d,denied){continue;}let(s,h)=observe(||owner.advance_targets(target,4096,denied).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(owner.target_demand(target,4096).unwrap(),d);}let(s,h)=observe(||owner.advance_targets(target,4096,g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));turns+=1;if owner.integer_bindings[0].is_some()&&owner.phase==0{assert!(owner.target_demand([RetainedDiagnosticTarget::Unsigned(foreign.borrow())],4096).is_err());}if matches!(s,RetainedCloneStep::Complete(_)){done=true;break;}assert!(turns<1000);}if cut.is_none(){assert!(done);let g=grant(RetirementDemand{copy_bytes:size_of::<Vec<MutationMessage>>(),depth:1,..Default::default()});let(rows,p)=owner.take(g).unwrap().unwrap();assert!(p.fits(g));assert_eq!(rows[0].target,[case["target"].as_str().unwrap()]);let mut ledger=MutationMessageLedgerRetirement::new(String::new(),rows);while !ledger.terminal_is_empty(){let d=RetirementDemand{copy_bytes:ledger.next_copy_byte_demand(),capacity_bytes:ledger.next_capacity_byte_demand(4096).unwrap(),release_bytes:ledger.next_release_byte_demand().unwrap(),depth:ledger.next_depth_demand().unwrap()};let g=grant(d);let(s,h)=observe(||ledger.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}}
 owner.begin_close();for _ in 0..10000{if owner.terminal_is_empty(){break;}let g=grant(owner.close_demand(4096).unwrap());let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));}
 for owner in [&mut original,&mut foreign]{for _ in 0..10000{if owner.terminal_is_empty(){break;}let g=grant(owner.next_close_demand(4096).unwrap());let(s,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(owner.terminal_is_empty());}
 }
}
